/** skill-marketplace.ts — Koto Skill Marketplace Frontend Logic */

import { installErrorBoundary } from '../shared/error-boundary';
installErrorBoundary();

export interface SkillItem {
  id: string;
  name: string;
  icon?: string;
  description?: string;
  author?: string;
  version?: string;
  category?: string;
  subcategory?: string;
  skill_nature?: string;
  enabled?: boolean;
  is_builtin?: boolean;
  rating?: number;
  rating_count?: number;
  tags?: string[];
  prompt?: string;
  system_prompt_template?: string;
  intent_description?: string;
  input_variables?: Array<{ name: string; type?: string; required?: boolean; description?: string }>;
  task_types?: string[];
  created_at?: string;
  [key: string]: any;
}

export interface ApiResponse {
  success?: boolean;
  skills?: SkillItem[];
  skill?: SkillItem;
  error?: string;
  total?: number;
  [key: string]: any;
}

export interface RepoInfo {
  repo: string;
  name: string;
  icon?: string;
  stars?: number;
  tags?: string[];
  skills_path?: string;
  branch?: string;
  [key: string]: any;
}

export interface GhSkillInfo {
  name: string;
  path: string;
  repo?: string;
  branch?: string;
  github_url?: string;
  is_installed?: boolean;
  [key: string]: any;
}

interface SubcatConfig {
  id: string;
  label: string;
  cls: string;
  group: string;
}

